//! Characterization of the v2 wire encodings, written before the family
//! extension (QUI-2003). The same tests must keep passing after the proto
//! gains the new fields.

use prost::Message;
use quip_proto::v1::{
    Algorithm, Backend, Capabilities, CoefficientEncoding, GeneratorAlgorithm, Hello,
    IsingProblemGenerator, Job, JobKind, Reject, RejectReason, Result as JobResult,
};

// Generated by the pre-SC-4 stubs (copied from `golden_wire.json` `messages`).
// These bytes must never change.
const OLD_CAPABILITIES: &str =
    "1a010120802028808002320973747265616d696e673208676f7665726e6f72380240044a02abcd5201015a010160026801";
const OLD_HELLO: &str =
    "0a056370752d301203746f6b5a311a010120f82328c0b802320973747265616d696e673208676f7665726e6f72380240044a02abcd5201015a010160016801";
const OLD_JOB: &str =
    "0a0401020304100118072080d095ffbc312a2412080a020001120201022880013880044014680170e8077a04e8030000820104f4010000320608011202dead";
const OLD_JOB_GENERATE: &str =
    "0a020506100318082081d095ffbc313a7108011202abcd1a201111111111111111111111111111111111111111111111111111111111111111222022222222222222222222222222222222222222222222222222222222222222222a2033333333333333333333333333333333333333333333333333333333333333333080023810";
const OLD_REJECT: &str = "0a04010203041007";
const OLD_RESULT: &str =
    "0a0401020304120e109ef6ffffffffffffff011a01051a1e08800110800418802020402a110a0c636861696e5f627265616b73120133222031313131313131313131313131313131313131313131313131313131313131312a204242424242424242424242424242424242424242424242424242424242424242";

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

/// Decode `bytes` as `M` and re-encode the result.
fn roundtrip<M: Message + Default>(bytes: &[u8]) -> (M, Vec<u8>) {
    let msg = M::decode(bytes).unwrap();
    let again = msg.encode_to_vec();
    (msg, again)
}

fn check_old_capabilities(caps: &Capabilities) {
    assert_eq!(caps.protocol_version, 2);
    assert_eq!(caps.backend, Backend::Cuda as i32);
    assert_eq!(caps.algorithm, Algorithm::Sa as i32);
    assert_eq!(caps.supported_kinds, vec![JobKind::IsingSample as i32]);
    assert_eq!(caps.max_nodes, 4096);
    assert_eq!(caps.max_edges, 32_768);
    assert_eq!(caps.native_topology_hash, Some(vec![0xAB, 0xCD]));
    assert_eq!(caps.features, vec!["streaming", "governor"]);
    assert_eq!(caps.stream_width, 4);
    assert_eq!(caps.encodings, vec![CoefficientEncoding::I32 as i32]);
    assert_eq!(
        caps.generators,
        vec![GeneratorAlgorithm::Blake3Chacha8V1 as i32]
    );
    assert_eq!(caps.max_degree, None);
    assert_eq!(caps.max_local_field_milli, None);
    assert_eq!(caps.exact_resolution_milli, None);
}

#[test]
fn old_capabilities_bytes_keep_their_meaning() {
    let (caps, again) = roundtrip::<Capabilities>(&hex(OLD_CAPABILITIES));
    check_old_capabilities(&caps);
    assert_eq!(again, hex(OLD_CAPABILITIES));
}

#[test]
fn old_hello_bytes_keep_their_meaning() {
    let (hello, again) = roundtrip::<Hello>(&hex(OLD_HELLO));
    assert_eq!(hello.miner_id, "cpu-0");
    assert_eq!(hello.session_token, "tok");
    let caps = hello.capabilities.unwrap();
    assert_eq!(caps.protocol_version, 2);
    assert_eq!(caps.backend, Backend::Cpu as i32);
    assert_eq!(caps.max_nodes, 4600);
    assert_eq!(caps.max_edges, 40_000);
    assert_eq!(caps.max_degree, None);
    assert_eq!(again, hex(OLD_HELLO));
}

#[test]
fn old_job_bytes_keep_their_meaning() {
    let (job, again) = roundtrip::<Job>(&hex(OLD_JOB));
    assert_eq!(job.job_id, vec![1, 2, 3, 4]);
    assert_eq!(job.kind, JobKind::IsingSample as i32);
    assert_eq!(job.generation, 7);
    assert_eq!(job.deadline_ms, 1_700_000_000_000);
    assert!(job.generator.is_none());
    let ising = job.ising.unwrap();
    assert!(matches!(
        ising.graph,
        Some(quip_proto::v1::ising_problem::Graph::Edges(ref e))
            if e.u == [0, 1] && e.v == [1, 2]
    ));
    assert_eq!(ising.encoding, CoefficientEncoding::I32 as i32);
    assert_eq!(ising.scale, 1000);
    assert_eq!(ising.h, vec![0xE8, 0x03, 0x00, 0x00]);
    assert_eq!(ising.j, vec![0xF4, 0x01, 0x00, 0x00]);
    assert_eq!(ising.num_reads, 128);
    assert_eq!(ising.num_sweeps, 512);
    assert_eq!(ising.anneal_time_us, 20);
    let provenance = job.provenance.unwrap();
    assert!(provenance.is_pow);
    assert_eq!(provenance.order_id, vec![0xDE, 0xAD]);
    assert_eq!(again, hex(OLD_JOB));
}

fn check_old_generator(generator: &IsingProblemGenerator) {
    assert_eq!(
        generator.algorithm,
        GeneratorAlgorithm::Blake3Chacha8V1 as i32
    );
    assert_eq!(generator.topology_hash, vec![0xab, 0xcd]);
    assert_eq!(generator.last_proof_block_hash, vec![0x11; 32]);
    assert_eq!(generator.miner_account, vec![0x22; 32]);
    assert_eq!(generator.base_salt, vec![0x33; 32]);
    assert_eq!(generator.salt_start, 256);
    assert_eq!(generator.salt_count, 16);
}

#[test]
fn old_lease_bytes_keep_their_meaning() {
    let (job, again) = roundtrip::<Job>(&hex(OLD_JOB_GENERATE));
    assert_eq!(job.job_id, vec![5, 6]);
    assert_eq!(job.kind, 3);
    assert_eq!(job.generation, 8);
    assert_eq!(job.deadline_ms, 1_700_000_000_001);
    check_old_generator(&job.generator.unwrap());
    assert_eq!(again, hex(OLD_JOB_GENERATE));
}

#[test]
fn old_reject_and_result_bytes_keep_their_meaning() {
    let (reject, again) = roundtrip::<Reject>(&hex(OLD_REJECT));
    assert_eq!(reject.job_id, vec![1, 2, 3, 4]);
    assert_eq!(reject.reason, RejectReason::TopologyMismatch as i32);
    assert_eq!(again, hex(OLD_REJECT));

    let (result, again) = roundtrip::<JobResult>(&hex(OLD_RESULT));
    assert_eq!(result.salt, vec![0x31; 32]);
    assert_eq!(result.nonce, vec![0x42; 32]);
    assert_eq!(result.job_id, vec![1, 2, 3, 4]);
    assert_eq!(result.solutions.len(), 1);
    assert_eq!(result.solutions[0].spins, vec![0x05]);
    assert_eq!(result.solutions[0].energy_milli, -1_250);
    let meta = result.meta.unwrap();
    assert_eq!(meta.reads, 128);
    assert_eq!(meta.sweeps, 512);
    assert_eq!(meta.device_access_time_us, 4_096);
    assert_eq!(meta.qpu_access_us, 64);
    assert_eq!(
        meta.extra.get("chain_breaks").map(String::as_str),
        Some("3")
    );
    assert_eq!(again, hex(OLD_RESULT));
}

#[test]
fn a_lease_with_tags_8_and_9_keeps_its_legacy_fields() {
    let job = Job::decode(&hex(OLD_JOB_GENERATE)[..]).unwrap();
    let mut bytes = job.generator.unwrap().encode_to_vec();
    // Tag 8 (length-delimited, empty) and tag 9 (32 bytes of 0xbb).
    bytes.extend_from_slice(&[0x42, 0x00, 0x4a, 0x20]);
    bytes.extend_from_slice(&[0xbb; 32]);
    let generator = IsingProblemGenerator::decode(&bytes[..]).unwrap();
    check_old_generator(&generator);
}
